import csv,datetime,collections
with open('dataset/employees.csv',newline='',encoding='utf8') as f:E=list(csv.DictReader(f))
with open('dataset/timesheet.csv',newline='',encoding='utf8') as f:S=list(csv.DictReader(f))
rates={e['PESEL']:float(e['hourly_rate']) for e in E}
# filter valid roster, valid date, and exact dedup
seen=set(); rows=[]
for r in S:
 if r['employee_id'] not in rates:continue
 try:d=datetime.date.fromisoformat(r['date'])
 except:continue
 key=tuple(r[c] for c in r if c!='id')
 if key in seen:continue
 seen.add(key); rows.append((d,r))
# start billing first Tuesday in calendar month
def start(d):
 x=d.replace(day=1)
 x+=datetime.timedelta((1-x.weekday())%7)
 if d<x:
  prev=(x.replace(day=1)-datetime.timedelta(days=1)).replace(day=1)
  x=prev+datetime.timedelta((1-prev.weekday())%7)
 return x
bad=[]
for emp in rates:
 er=sorted([(d,r) for d,r in rows if r['employee_id']==emp])
 cum=collections.defaultdict(int)
 for d,r in er:
  period=start(d); cum[period]+=int(r['hours_worked'])
  actual=float(r['salary_amount'])/rates[emp]
  if actual!=cum[period]:bad.append((r['id'],emp,r['date'],period,cum[period],actual))
print('kept rows',len(rows),'cumulative mismatches',len(bad))
print(bad[:100])
# show final cumulative hours vs aggregate by period (trivial) and final observed salary values
for emp in rates:
 er=sorted([(d,r) for d,r in rows if r['employee_id']==emp])
 vals={}
 for d,r in er:vals[start(d)]=int(float(r['salary_amount'])/rates[emp])
 print(emp,[(str(k),v) for k,v in sorted(vals.items())])
PY","workdir":"/app","yield_time_ms":10000,"max_output_tokens":30000});
