import csv,datetime,collections,itertools
with open('dataset/timesheet.csv',newline='',encoding='utf8') as f:S=list(csv.DictReader(f))
with open('dataset/employees.csv',newline='',encoding='utf8') as f:E=list(csv.DictReader(f))
V={e['PESEL']:float(e['hourly_rate']) for e in E}
M={'15720759071':'75020759171','16102016795':'96102016751','62020111425':'65020111422','68011910138':'68011810139','84731091580':'87031491580'}
wd=1
def anchor(d):
 a=d.replace(day=1)+datetime.timedelta((wd-d.replace(day=1).weekday())%7)
 if d>=a:return a
 p=d.replace(day=1)-datetime.timedelta(1); x=p.replace(day=1);return x+datetime.timedelta((wd-x.weekday())%7)
for target in M.values():
 sources={target}|{u for u,t in M.items() if t==target}
 rows=[];seen=set()
 for r in S:
  if r['employee_id'] not in sources:continue
  try:d=datetime.date.fromisoformat(r['date'])
  except:continue
  # Dedup after normalizing employee ID
  k=tuple((target if c=='employee_id' else v) for c,v in r.items() if c!='id')
  if k in seen:continue
  seen.add(k);rows.append((d,r))
 print('\nTARGET',target,'rows',len(rows))
 # Any ordering of same date increments; compare salary q to cumulative totals before/after all rows in same date
 cum=collections.defaultdict(int); bad=[]
 for (p,d), gr in itertools.groupby(sorted(rows,key=lambda x:(anchor(x[0]),x[0])),key=lambda x:(anchor(x[0]),x[0])):
  group=list(gr); before=cum[p]; after=before+sum(int(r['hours_worked']) for _,r in group)
  qs=[float(r['salary_amount'])/V[target] for _,r in group]
  # a valid q can be any sequential cumulative in some order; at least max should after
  if max(qs)!=after:bad.append((str(d),before,after,[(r['employee_id'],r['hours_worked'],q) for (_,r),q in zip(group,qs)]))
  cum[p]=after
 print('period hours',cum,'bad date-final counter',len(bad),'samples',bad[:10])
